import pandas as pd, numpy as np, collections

# Reload data (fresh interpreter!)
DATASET_PATH = "chunks_csv/moran_local_2023_transport.csv"
df = pd.read_csv(DATASET_PATH)
adj = pd.read_csv(ADJACENCY_PATH)

# The energy‐use column is ‘Transport_value’ (see head printed earlier)
value_col = 'Transport_value'

# 1. Build symmetric neighbour list
weight_dict = collections.defaultdict(set)
src_col, nbr_col = adj.columns[:2]
for src, nbr in adj[[src_col, nbr_col]].itertuples(index=False):
    weight_dict[src].add(nbr)
    weight_dict[nbr].add(src)          # assume undirected adjacency

# 2. Z-score the transport values
z_series = (df[value_col] - df[value_col].mean()) / df[value_col].std(ddof=0)
z_series.index = df['borough']

# 3. Local Moran’s I_i = z_i * Σ_j w_ij z_j
def local_I(b):
    neigh = weight_dict[b]
    if not neigh:           # isolated (should not happen)
        return np.nan
    return z_series[b] * z_series[list(neigh)].sum()

obs_I = {b: local_I(b) for b in z_series.index}

# 4. Monte-Carlo significance (999 permutations)
perm_n = 999
rng = np.random.default_rng(42)
perm_I = {b: [] for b in z_series.index}

for _ in range(perm_n):
    shuffled = pd.Series(rng.permutation(z_series.values), index=z_series.index)
    for b in z_series.index:
        neigh = weight_dict[b]
        if not neigh:
            perm_I[b].append(np.nan)
            continue
        perm_I[b].append(shuffled[b] * shuffled[list(neigh)].sum())

p_val = {}
for b in z_series.index:
    greater_eq = np.sum(np.array(perm_I[b]) >= obs_I[b])
    p_val[b] = (greater_eq + 1) / (perm_n + 1)   # pseudo-p

# 5. Classify HH / LL
results = []
for b in z_series.index:
    if obs_I[b] > 0 and p_val[b] < 0.05:
        if z_series[b] > 0:
            results.append((b, 'HH', obs_I[b]))
        elif z_series[b] < 0:
            results.append((b, 'LL', obs_I[b]))

# 6. Print diagnostics and FINAL ANSWER line
for b, tag, I in results:
    print(f"{b}: {tag}, I={I:.4f}, p={p_val[b]:.4f}")

if results:
    answer = ", ".join(f"{b} ({tag}, I={I:.4f})" for b, tag, I in results)
    print("FINAL ANSWER:", answer)
else:
    print("FINAL ANSWER: none")
